begin;

with approved(template_key, subject_text, body_text) as (values
('state1','گزارش وضعیت امور | [تاریخ گزارش] | وضعیت مطلوب',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nبررسی آخرین اطلاعات ثبت‌شده در سامانه «مدیریت وظایف» نشان می‌دهد که در حال حاضر هیچ‌یک از فعالیت‌های حوزه مسئولیت شما در وضعیت «هشدار» یا «دیرکرد» قرار ندارد.\n\nخلاصه وضعیت: ۰ مورد هشداری | ۰ مورد دیرکردی\n\n[استیکر]\n\nاز همراهی و اهتمام شما در پیگیری، انجام به‌موقع و به‌روزرسانی امور سپاسگزاریم.\n\nتاریخ گزارش: [تاریخ گزارش]\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول'),
('state2','گزارش وضعیت امور | [تاریخ گزارش] | یادآوری',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nبررسی آخرین اطلاعات ثبت‌شده در سامانه «مدیریت وظایف» نشان می‌دهد که [تعداد هشدار] مورد از فعالیت‌های حوزه مسئولیت شما وارد دوره «هشدار» شده‌اند و موعد پایان آن‌ها نزدیک است.\n\nخلاصه وضعیت: [تعداد هشدار] مورد هشداری | ۰ مورد دیرکردی\n\n[استیکر]\n\n[جدول امور هشداری]\n\n[جدول امور منتظر پاسخ]\n\nلطفاً ضمن بررسی موارد فوق، برنامه‌ریزی و پیگیری لازم را به‌منظور انجام آن‌ها پیش از فرارسیدن موعد مقرر در دستور کار قرار دهید.\n\nتاریخ گزارش: [تاریخ گزارش]\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول'),
('state3','گزارش وضعیت امور | [تاریخ گزارش] | نیازمند توجه',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nبررسی آخرین اطلاعات ثبت‌شده در سامانه «مدیریت وظایف» نشان می‌دهد که [تعداد دیرکرد] مورد از فعالیت‌های حوزه مسئولیت شما از موعد تعیین‌شده عبور کرده و در وضعیت «دیرکرد» قرار گرفته‌اند.\n\nخلاصه وضعیت: [تعداد هشدار] مورد هشداری | [تعداد دیرکرد] مورد دیرکردی\n\n[استیکر]\n\n[جدول امور هشداری]\n\n[جدول امور دیرکردی]\n\n[جدول امور منتظر پاسخ]\n\nلطفاً موارد فوق را بررسی کرده و اقدامات لازم برای تکمیل آن‌ها و به‌روزرسانی آخرین وضعیت هر فعالیت را در اسرع وقت انجام دهید.\n\nتاریخ گزارش: [تاریخ گزارش]\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول'),
('state4','گزارش وضعیت امور | [تاریخ گزارش] | پیگیری جدی',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nبررسی آخرین اطلاعات ثبت‌شده در سامانه «مدیریت وظایف» نشان می‌دهد که [تعداد دیرکرد] مورد از فعالیت‌های حوزه مسئولیت شما در وضعیت «دیرکرد» قرار دارند و نیازمند پیگیری جدی‌تر هستند.\n\nخلاصه وضعیت: [تعداد هشدار] مورد هشداری | [تعداد دیرکرد] مورد دیرکردی\n\n[استیکر]\n\n[جدول امور هشداری]\n\n[جدول امور دیرکردی]\n\n[جدول امور منتظر پاسخ]\n\nخواهشمند است موارد فوق با جدیت بررسی شده و اقدامات لازم برای تعیین تکلیف، تکمیل و به‌روزرسانی وضعیت آن‌ها در اولویت قرار گیرد.\n\nتاریخ گزارش: [تاریخ گزارش]\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول'),
('state5','گزارش وضعیت امور | [تاریخ گزارش] | اقدام فوری',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nبررسی آخرین اطلاعات ثبت‌شده در سامانه «مدیریت وظایف» نشان می‌دهد که [تعداد دیرکرد] مورد از فعالیت‌های حوزه مسئولیت شما در وضعیت «دیرکرد» قرار گرفته‌اند و نیازمند رسیدگی و اقدام فوری هستند.\n\nخلاصه وضعیت: [تعداد هشدار] مورد هشداری | [تعداد دیرکرد] مورد دیرکردی\n\n[استیکر]\n\n[جدول امور هشداری]\n\n[جدول امور دیرکردی]\n\n[جدول امور منتظر پاسخ]\n\nخواهشمند است موارد فوق در اولویت پیگیری قرار گرفته و اقدامات مقتضی برای تعیین تکلیف و تکمیل آن‌ها در سریع‌ترین زمان ممکن انجام شود.\n\nتاریخ گزارش: [تاریخ گزارش]\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول'),
('followup','یادآوری پیگیری امور | [تاریخ گزارش]',E'[عنوان مخاطب]\n\nبا درود و مهر،\n\nپیرو آخرین گزارش ارسال‌شده درباره وضعیت امور در تاریخ [تاریخ آخرین ارسال]، تاکنون پاسخی از سوی شما دریافت نشده است.\n\nخواهشمند است آخرین وضعیت فعالیت‌های حوزه مسئولیت خود را در سامانه «مدیریت وظایف» بررسی و در صورت نیاز به‌روزرسانی فرمایید.\n\nبا تشکر و احترام\nسامانه خودکار پایش و پیگیری امور\nشرکت خودروسازان بم\nواحد مهندسی محصول')
)
update public.email_templates e
set subject_template=a.subject_text, body_html=a.body_text, updated_at=now()
from approved a where e.template_key=a.template_key;

with approved(template_key, subject_text, body_text) as (select template_key,subject_template,body_html from public.email_templates where template_key in ('state1','state2','state3','state4','state5','followup'))
update public.message_templates m
set subject_text=a.subject_text, body_text=a.body_text, updated_at=now()
from approved a where m.template_key=a.template_key;

commit;
